122	// Criterion 4: a Bearer challenge, with and without credentials.
123	func TestCatalogHTTPBearer(t *testing.T) {
124		run := func(t *testing.T, user, pass string) (tokenAuth, firstAuth string, out Outcome, imgs []Image) {
125			t.Helper()
126			var tokAuth, first atomic.Value
127			tokAuth.Store("")
128			first.Store("")
129			var srv *httptest.Server
130			srv = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
131				if r.URL.Path == "/token" {
132					tokAuth.Store(r.Header.Get("Authorization"))
133					_, _ = fmt.Fprint(w, `{"token":"tok123"}`)
134					return
135				}
136				auth := r.Header.Get("Authorization")
137				if first.Load() == "" {
138					first.Store("seen:" + auth)
139				}
140				if auth != "Bearer tok123" {
141					w.Header().Set("Www-Authenticate", fmt.Sprintf(`Bearer realm="%s/token",service="x"`, srv.URL))
142					w.WriteHeader(http.StatusUnauthorized)
143					return
144				}
145				_, _ = fmt.Fprint(w, catalogJSON("nginx"))
146			}))
147			t.Cleanup(srv.Close)
148			imgs, out, err := catalogOutcome(t, CatalogSearcher{}, Target{APIURL: srv.URL, Username: user, Password: pass}, "nginx")
149			if err != nil {
150				t.Fatal(err)
151			}
152			return tokAuth.Load().(string), first.Load().(string), out, imgs
153		}
154	
155		t.Run("credentials go to the token endpoint only", func(t *testing.T) {
156			tok, first, out, imgs := run(t, "u", "p")
157			if want := "Basic " + base64.StdEncoding.EncodeToString([]byte("u:p")); tok != want {
158				t.Errorf("token endpoint Authorization = %q, want %q", tok, want)
159			}
160			// internal/oci sends Basic to the registry itself first, gets the Bearer
161			// challenge, then replays with the token (the pages carry Bearer, which
162			// the handler enforces by only answering 200 to "Bearer tok123").
163			if want := "seen:" + "Basic " + base64.StdEncoding.EncodeToString([]byte("u:p")); first != want {
164				t.Errorf("first catalog GET = %q, want %q", first, want)
165			}
166			if out.Verdict != VerdictOK || len(imgs) != 1 {
167				t.Errorf("out = %+v imgs = %v", out, imgs)
168			}
169		})
170		t.Run("anonymous sends no Authorization", func(t *testing.T) {
171			tok, first, out, _ := run(t, "", "")
172			if tok != "" || first != "seen:" {
173				t.Errorf("token auth = %q, first = %q, want none", tok, first)
174			}
175			if out.Verdict != VerdictOK {
176				t.Errorf("out = %+v, want ok", out)
177			}
178		})
179	}
